  VALUES 
    (513::BIGINT, 'Muy claro, muy dinámico. Las clases son entretenidas. Califica con lupa, pero justo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6cd9b30a072d14fb04880f51659a5ea72e9c1305e959fce85976432288fcd463'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'No lo recomiendo, no es mal profe pero es una persona un poco hostil'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2026-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2e2bdc2926b306e225c4a45317a154d4ca334f1681f96524a031b280503ae986'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, '3 años de carrera y el facil entra en el top uno de peores profes'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'edd2ebc9e4717b1a8f6a9289638207756c6280b97a0eff98206f8c1e132cedbe'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'En el curso de verano se realizaro 6 exámenes y 6 tareas. Además, se imparten dos clases presenciales y dos asincrónicas, por lo que se requiere ser bastante autodidacta. En los exámenes, algunos ejercicios se basan en las tareas, lo cual permite prepararse mejor; sin embargo, la calificación justo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos exámenes']::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, '56ec39d78cfd9d2c2e9efd2cdd03c7af67f5f748c5f0cb07b8677b63e5872e66'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Gran profesor. Brinda muchas ayudas y explica súper bien. Exámenes y tareas relativamente sencillas. Un poco picky con ciertas cosas pero en general 10/10.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'f6db85ff90baca4f7e085e4fb561e3ae0d39f29e2b7bd5198d52bba5c0d69bbd'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Buen profe, la consulta es buena con el, ayuda bastante y es bueno que el vea que le interesa el curso, recomiendo llevarlo con el.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '1b719c4d02eb652f3eb63a7ec2cfbf24592000c2a177c25f6ef86acefc7ea62e'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'En verano, semipresencil. Fueron seis exámenes cortos de una hora, más de la mitad sacada de las tareas. Si uno le pone, el profe ayuda y califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '47084679c219dfc10021a94d240e96fa3a9d9afbdc51bc201434040c75550b2d'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Llevado en verano y la verdad mucha tarea y los exámenes más o menos fáciles pero se pone a bajar puntos por cosas que nada que ver.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '83664783d6b7a28cf81f7573602358e0ac3553884f0fdcf94f55c52c406fb67b'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Muy bueno, muy claro, responde consultas rápido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a1a2832a1baf092672d4d77985332456aff7c0b6ded4374b39655a241ed59312'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c8e83db95a73f92ed5691eea187a88a3ddf5dded0654b1b7b9f7f6641174c5b3'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'El grupo era semiprsencial y teníamos clase los miércoles y para los viernes nos dejaba videos y ejercicios. El curso es se pasa bien si uno lo lleva al día. El profe explica claro y atiende consultas rápido. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9715f667a91ac4fff7ac21d5bc81d39d286afaef46665986108cfa86763a2fc3'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Va a perder mucho tiempo en tareas y quices (que son de poca ayuda), lo que vuelve el curso pesado. Es necesario llevar todo al día o perderá esos quices y tareas que tanto le importan. Da puntos por corregir los tantos errores que tiene en clase (una carnicería y se pierde tiempo)'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2024-06-03T00:00:00+00:00'::TIMESTAMPTZ, '625af2bab280e277622dc19351c3d1e324a35b167946c32e33c4f603a458badd'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'El profe Luis da buenas clases, le preguntan lo que sea y siempre tiene una respuesta, ayuda con puntos extra, algún quiz optativo o algo, y atiende consultas por Telegram muy rápido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '0dab10b7f2d1a6cc1cf4b05c3e84c013077f17541e941581fb26d5fc0073391b'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'da puntos extra si participa, califica suave los exámenes, explica súper bien y muy claro. mi curso favorito del semestre. el profe luis es mi papá, no dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '920791fb4d3195f2a51a321d7339e7f997925bd30c92a84bc7e7d7b9abea4aca'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'd29cdb491986e37ce43c46b0625226f47089c3d664c97dbd410d2577b349d3f3'::TEXT, ARRAY[1712, 1713]::BIGINT[]),
    (513::BIGINT, 'Muy ordenado, deja tareas todas las semanas y si uno las hace pasa de fijo. Es medio exugente a veces pero le ayuda a uno en todo lo que puede y cualquier duda que uno tenga, se la explica las veces que uno necesite .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-22T00:00:00+00:00'::TIMESTAMPTZ, '38a5a6ae70bdf58feec51928c374c10daf3244277aca7ccace89aea00f1f6e23'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '18d02e15e109b2b4129d197996773ddae7ea76cf59da51b2720579bb18c50c9b'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El profe explica bien pero hace que el curso sea muy pesado por la cantidad de tareas y la extensión de las mismas. Hay otros profes igual de buenos pero con los que el curso no se hace tan pesado.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3fce2215ab172c3061993e5ee665bd313c899af0fa34c34d92b1d234cd5367cb'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9b62618e1000a85049c7595f8c4147e314f47b5ff5cd02d129c7dbb71950f379'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'No es que el curso sea tan difícil, pero tampoco es complicado y el profe lo pone todo muy claro. Si usted hace las tareas y lleva la materia al día, los quices están pasados y para los exámenes solo hay que repasar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-04-10T00:00:00+00:00'::TIMESTAMPTZ, 'c6b341a45432449892892607ee337f8bffc9ac12340eee7437f88e086fcdf023'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2023-02-08T00:00:00+00:00'::TIMESTAMPTZ, '403bdd5257fcd87b0e504ea8ab0021530e0c1d88881d06ff377934cd072675f1'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Muy bueno! Se le entiende bien porque explica las veces que haga falta. No es rudo para calificar. Se pueden hacer preguntas en cualquier momento, en clase, en consulta, por telegram. Los quices ayudan mucho porque son copiados de la tarea.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'def3a3d4ca6925db52eb1d96b846f17c365d9a71c9b7087071b99995b8f20395'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'El mae es buena gente, pero no sabe explicar lo explica muy matemático, todas las clases hay quizz y deja tareas muy largas que nunca las revisas, los quizz tienen un valor tiene mucho peso en la evaluación. Si lo quiere llevar con el tiene que ir a clases aparte para pasar.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, '7b4c728da2f3260e29d6bae3d3abb4916868edb2c1717f65c010f06c49691af9'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Se le entiende bien, clases entretenidas, quices frecuentes y fáciles, puntos extra si uno quiere pasara la pizarra. Si uno lleva la materia al día el curso se pasa casi que solo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'bea4c82c245fcee750f8a614bdfdbb0b7cb444d185eedaa5e25b8082ba71f107'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Pura vida, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-27T00:00:00+00:00'::TIMESTAMPTZ, '9ddaafd1055ed26032b44d5b541510029907ca6cd27f17804540fab23a09a40d'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Demasiado acosador con las mujeres. Califica demasiado tieso, no ayuda en nada y no se aprende nada mas que seguir sus reglas inventadas'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '8cc3d6fa52a89629d23c991df7fed27e47f96d8acb8369f3dd9564b896924b61'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Muy bien profe, quices seguidos pero copiados de la tarea, puntos extra si uno quiere participar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'f4369d4ee83dd7668bce5ad1a5b8de081d55e74a92f6b44f329f42e7d0fd91ab'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'En general es bueno. Deja tareas cada día, pero después los quices son de la tarea, así que si uno las hace ya le fue bien en el quiz. No se limita a la materia de examen sino que va más allá y enseña cosas que después le sirven a uno en otros cursos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-21T00:00:00+00:00'::TIMESTAMPTZ, '7c36d365cac4d8ad68f13d1740e686cf50deb9f8938069612a9a72994a6718e0'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'En general es un buen profesor. Las clases son claras y explica las veces que sean necesarias. Sin embargo, deja tareas semanales muy largas que son calificadas en quices cada semana y que no ayudan para los exámenes. Además, explica temas que no entran en los parciales.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-17T00:00:00+00:00'::TIMESTAMPTZ, '301c256c487977abf4ca4a7a3d6a82dd05ae77e660a890bb1d9cc81a19e88faa'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Deja tareas muy largas y algunos problemas ni siquiera los había explicado. Es muy estricto pero da puntos por participación y eso lo puede salvar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Da crédito extra']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, '09b297bd905272009d1e1a1ba3d45cdbb4bf74d0773ce8a85875044d69f11606'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'La verdad es que me cogio tarde para coger el ritmo, pero el profe es muy bueno, lo malo fue que no le puse desde el principio, pero las clases estaban bien y el profe ayuda en consulta, presencial o virtual.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '0e8049c7a995360ffe1d1c52a800dc284fd09f69ba0fbb3750fe5cb2b1268c9b'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Es buen profesor. Si quiere (o tiene que) llevar con él, puede estar tranquilx. Es un profesor serio, pero que explica con buen interés de dar la materia. Es muy organizado. Haga las tareas (son muy útiles), aproveche los puntitos por participación, y aproveche las horas de consulta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3adea06f89adae5ff1f980b05e8532436adcc53d02da0fb71f75901f11ea72d6'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Explica bien, es entretenido y se entusiasma, califica justo. A ver si cojo el siguiente curso con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '1ab2b7672862a9f0d9d8804861d5a41ab4417040102e1d25c142dba460b1d039'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Al principio me sorprendió que "virtual" es que no había clases, pero el profe siempre estuvo en contacto mandándonos guías, ejercicios, videos con la materia. Total, uno se responsailiza por estudiar por su cuenta, pero tampoco está solo. El profe ayuda mucho y los materiales son un gran apoyo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '326a638fc225142244c977fd68c6bddfcda9865ac0e89e74f843d647c550429c'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Se puede decir que le regalan el salario, porque no da una sola clase sincrónica. Su asistente es un friqui matemático reprimido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-09-07T00:00:00+00:00'::TIMESTAMPTZ, '343185123fe65b41e967e38ca858f0650cb32a4ba42267370339294a852a2086'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Deja tareas todas las semanas de al menos 15 ejercicios, si las lleva al dia sirve mucho para los exámenes, por otro lado esas tareas tienden a acumularse si tiene otros trabajos, explica muy pocos ejercicios en clase, virtualmente no dejo apuntes a comparación de otros profesores, califica duro'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1f55355911ea31a6890fe8aa75cd735a89a34b7124851cda37bfa5738633003d'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Buen profe. Las tareas ayudan mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '171bd4662a075aec96dc1b1e49c6de485c8fa96d19791e09ae163ec629c7c874'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Él cree que solo su clase se lleve, es excesivo el número de ejercicios que asigna, al menos unos 16 ejercicios por semana.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '62da6ed2d8fad47427f3b8d445f12ab33344b8bee59228c3b6edf6b1a60b6639'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Muy organizado y puntual. Cada semana nos daba una lista de temas para estudiar en el folleto y una lista de ejercicios. Si lo cumplís, ya vas bien. En clase se refuerza lo que uno estudió.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes', 'Aspectos de calificación claros']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c04f5b77b9e329dd5766fe5ca89c2afafbf5c48efc4904f3715906c05943a1bd'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '53f86fe7f1c863098b8917e1bb089cbf3a07d80383cc6a538e9496266725b7df'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '69ca2cb8ef8fb46e41629af34b6d681bb9ff0604dc390be647646e1e5c7cf689'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'De los mejores profes virtules que he tenido. La evaluación quedó clara desde el primer dia de clases, la materia se entiende bien. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '7c7c3c0d1a2b655f734c0c98949ea40f2a5042f539e236afeffc739e46344f7d'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '7ebf0ab6f50a64561c43f28644a3e06627e62a38c6ea150850a455f10bbbd3e8'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'La verdad no lo recomiendo, su sistema de calificación es un desastre y de su asistente mejor ni hablemos, es difícil que te responda alguna duda sin que se ponga espeso o directamente la evite, prácticamente hay que ser autodidacta o ver las clases de otro profe.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2022-05-29T00:00:00+00:00'::TIMESTAMPTZ, '3ff7666f0954f3c689c6341883f65421bfa1d2c19749cb69cdfcae2aacd4c6e0'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Las clases se entienden bien, las tareas del libro ayudan. El profe es estricto, pero al final clifica justo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '0c5b6f69889d3ffb2fd68062625f71bc02a7f8c9070dde4c2958c163cb72ff4f'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '5429a3f254ca7dfb6cdb7d66693c6e5513b9091c1e3e86be2c9fe36e481cb540'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'a16536dce83a8148ac5eff9be5d3d587f28b04dcc5c815a806a29fb69e7a353d'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Muy buen profe, explica muy claro, deja tareas seguidas pero después los exámenes son muy parecidos. Estricto pero en general muy recomendable.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes']::TEXT[], '2022-01-28T00:00:00+00:00'::TIMESTAMPTZ, '1be4a42b986e77e9d42f7e57b2f2fe91a94dcb42973ba198f0c92453e6380c76'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Da crédito extra']::TEXT[], '2022-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'a6fe44b94c7afbb7ca753e3a8456c8dc57544bf506deaad2f5a020be3bbecf58'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Buen profe. Yo había llevado es te curso varias veces pero ahora en verano sí logré pasarlo. Aclara dudas en clase y por telegram a cualquier hora. Los exámenes se parecen a los ejercicios hechos en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'b26b00c636d0ea21b46fc32e93a949396e6b470c80ba14f126a7e38d63bf35b3'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Excelente profe, super organizado y puntual. Explica muy claro, da instrucciones muy precisas para las tareas y exámenes, califica suave.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2022-01-23T00:00:00+00:00'::TIMESTAMPTZ, '3787d516c7200fdacf40011efdf9ff98f2fd582c9d7a32d732b1f14c01c654ba'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Este profesor y su asistente son la pareja perfecta, su forma de calificar es exageradamente confusa, la asistente es demasiada estricta y ambos se desentienden de dar ayuda, si uno tiene una tardía y justifica, a pesar de tener el visto bueno de él no lo califica, es el peor profesor que conozco.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'ef92b5812f03207b58aa83f198a4bdcdfb21e712623d657a49d3000038a8767c'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Deja tareas de muchos ejercicios todas las semanas, al igual, hay quices todas las semanas. Responde dudas en clases pero a la hora de calificar la asistente es un dolor.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'e5639999e1391bf4a5ab4f399f565605c98ecc17e2e6b6ff66f1dc6ea51802d2'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Mal profe! Debería de ahondar más en sus explicaciones en clase y preparar al estudiante para los exámenes con preguntas que estén a la altura y no con preguntas elementales. La asistente es un dolor que baja puntos por todo en tareas y quices'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'b18b069d971b866c05dcc9e8123374c00e3ce93f84a27ac75c709606a17c27f7'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Es un profesor excelente, explica muy bien la materia. Dejaba tareas para las semanas pares y para las impares dejaba quizes, así que el curso si se hace más pesado con el, pero en general lo recomiendo, es muy bueno, atiende dudas por telegram casi que siempre'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '521ad674088aae6b1cb6d84a91fd6484d13181e8d28306710f5b8dd9f6a8dadd'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Muy buen profe, organizado, claro, atiende consultas a cualquier hora. Veo algunos se quejan de la asistente, pero no es que los asistentes cambian cada semestre? O sea, qué culpa tiene el profe de que un semestre le pusieron una asistente difícil.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b09cbf526b6b2dd873f7bf8f11695d1d98417932ecde5d93ef4e8f6c9c253e6f'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'La carga académica que exige es exagerada pero explica bien el problema de este curso es la asistente, busca cualquier detalle para bajar puntos y no calificar todo el ejercicio, hace la vida del estudiante imposible, si puede no matricule con este profe'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7535c0546b59bac59857409cffd315b178186449167db3330d69c13d91042e0c'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Hay tareas y quices a cada rato, pero son sacados del libro, así que ninguna sorpresa. Las evaluaciones de cátedra pueden ser más rudas, pero el profe más bien se peleaba con la cátedra para que no las hicieran así. En general bastante bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'eb3cfa918802f35b782eed8d7a10aa0dd6aea1ee792255cc603fbbea58948df6'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Explica todo lo que se le pregunte en clases , en consulta o hasta el fin de semana. Tareas y quices parecidos a los exámenes. Los exámenes valen solo 50% así que no se confíe porque sin quices ni tareas no va a pasar ni con 100 en exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3861501d4d0eebcd1a08f3562a49e2cc3b1e296cf12f7f7b29a605c673724fce'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Virtual. El curso con él abarca mucho tiempo, requiere mucho esfuerzo, deja muchísimos ejercicios de tarea semanales. Las clases son provechosas y explica cuántas veces sea necesario, es muy claro y preciso. No anda con pelos en la lengua. Graba todas las clases, pero es importante asistir.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '43fec6cb0235c0dd44a0dcfbae52171f6f76310ec76ee82b1aa57cb83e6a3ad4'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Si quiere sobrevivir el curso con este profe tiene que ser AUTODIDACTA SI O SI. Los ejercicios que el profe hace no se comparan del todo con los que salen en quices y examenes de cátedra. Se debe profundizar en la materia por su propia cuenta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '81f617bc117e70be4285b6da1898457b32203a1b7cc7b328cd2a653ee6054a8e'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Hay tareas cada quince días y son bastante largas, sirven para comprender la materia, sin embargo, no son tan provechosos comparándolos al nivel de las evaluaciones de la cátedra. Si estudia de manera autodidacta no le servirá mucho la clase porque va algo lento y hace ejercicios simples.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '99cdd82aae61101174b4bc17e005b7af040e5ff445ae931889841e5bacce5dc4'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Deja demasiados ejercicios de tareas todas las semanas y revisa muy pocos ejercicios de los que deja, los ejercicios que explica en clase son muy fáciles comparados a los de los exámenes y quices de cátedra. NUNCA aclara las dudas, siempre contesta las dudas con otras preguntas y es muy irónico.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '200cab0a0dada447d6fd28e93d67f98649621673763b4c58d0f72c43396adf88'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'En este curso teníamos una clase sincrónica y para la otra nos tocaba estudiar o hacer ejercicios. El profe aprovechaba bien el rato sincrónico haciendo ejercicios y aclarando dudas. Las consultas por correo o telegram siempre las atendía pronto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c6f569ab5782395fae3c4cb7c2d1bdbbe60197e759097906519e8c58853b8309'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El profe es una buena persona pero a la hora de dar clase...mmm no tanto. Sabe mucho del tema pero en clase se dedica a resolver ejercicios "patito". Para salir bien en el examen hay que ser autodidacta y buscar ayuda porque él no hace ejercicios tipo examen.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '54ea2bb20bd5b6f8ed9f18abd89f1232a2f81baa937ffb79976a94c4e551a2cf'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Las clases no sirven de mucho, es solo el profe resolviendo ejercicios. Deja tareas del folleto que sirven mucho de práctica, a veces son muchos ejercicios y se vuelven abusivas . Es un buen profe y si se hacen todas las tareas se logra pasar más fácil. Es estricto con formatos y horas de entrega.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd27f953b9872dd4039222f590f7d0d7218b1999eeaee99d372fe04d958608894'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El Profesor, da muchas tareas, en su mayoria son largas es bueno porque se practica pero a veces son un toque pesadas, las clases con largas, algo importante es un profesor que siempre quiere basurear al estudiante, y es pesado tambien. Si pueden ahorrense el estres.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2021-09-23T00:00:00+00:00'::TIMESTAMPTZ, '93251bad72a7c5c910b99008be77a26d74679d261150b48389471be77812edc3'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Uno de los mejores profes que he tenido, se ve que domina la materia y sabe explicarla. Lea y siga bien las instrucciones y verá que el curso es fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-29T00:00:00+00:00'::TIMESTAMPTZ, '6bc933d3d80cfb103ef33e86848184d496118c797db5ef9ccba63c808fdb52be'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Sin duda el peor profesor que he tenido en mi vida. Le agrega un peso exagerado a un curso fácil. Aunque pases, el tratará de bajar lo más posible tu nota.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'ea4b9434e5c1cca98c68d93caa082da543352d3f57f9731670b0a9bcb7892846'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Ponerle desde el principio, ya que de las dos sesiones semanales da una sincronica y la otra es asincronica para practicar y hacer tarea, deja quiz todas las semanas y si no llevas la materia al día se puede complicar el curso, pero en general buen profe. Requiere bastantes horas de estudio indivi'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '0231e41ebf8a9605dd0e278d91c59c41ddfad50959571e82d8f5e3f3a6f1ef04'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El profe es bueno, explica claro, nos da puntos por participar y el folleto ayuda mucho. Los parciales no valen tanto (50%) pero quices y tareas sí (el otro 50%) así es que hay que llevar la materia al día y no confiarse en estudiar solo para los examenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '52d097b37b2ccefbf365eaec129c34fbf2988ecdc9f116a5c713dd2baaf7e1cb'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'La verdad no entiendo porque tiene nota tan baja. Es una persona muy directa y clara, si usted sigue las reglas y le pone al curso como se debe, pasa sobrad@. Deja quices todas las semanas (2 ejercicios fáciles) y tareas que sirven para ir estudiando. Contesta claro las consultas y reclamos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '386db233d8c99bfda6d5d61943e7bc38132f7e54fbcb87c2140c1b5887c27711'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, '539ab383bf0a3eea692758958d001de44f1bdf75e268cc459dd5c7dd253df8be'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Explica muy bien, da puntos por participar en clase (voluntario), los quices son copiados del libro, las instrucciones para los quices son rígidas pero claras, nada más sígalas con cuidado y le va a ir bien. Asista a clases, haga las tareas y al final el profe le ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '3bd8ac683dc4221b390243964cdec94022fde7059b320b2460ef5d0f73a0ea60'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Excelente profesor, cosas de interés: Deja quices todas las semanas, la participación en clase es importante, la materia es sencilla y él explica lo que se necesita, solo una clase a la semana yyyy la asistente es un dolor de maracas, cualquier error de una se lo pone malo y ni reclamar deja.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '058621d6b02daa5ae88074a852ac72849bd6be81223b6bda074d86eea32e5516'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'La materia del curso es bastante facil y el profe complementa con las clases que da (sola da una) . Lo malo es que manda quices las 16 semanas y la asistente es un dolor , le baja a puntos por cualquier cosa y uno no puede reclamar porque según ella siempre tiene razon'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '2b3e7b2e435ab4a9d6c4d609fb2c57bc2412fcc0b0d906feae06ee8295e4027f'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Buen profesor, explica muy bien y hace bastantes ejercicios para que el tema quede claro. Da puntos extra por participación en clase. Hace quices todas las semanas pero son ejercicios de su mismo libro. Haga todo lo que digan las guías semanales y el curso se pasa solo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '03b2bf165555b2eea361c1907facc05179ca050d993f507771824031030b7f18'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '09ca0e45dc64e4ebee46812c1323c621c935167930f0a55cc2822b14eea52049'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'El profe es muy bueno y todo, pero la asistente es un completo dolor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '17a439d44f326755b37ccafe9933785cf9f32d01ace4d9bf355be653ae027b89'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El profe es realmente bueno, es necesario ponerle desde el principio para no estar preocupado al final, y aprovechar las horas de consulta. Da puntos por participación.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, '807b9c0e41f12baabc7ccf50ee923a84f99737a17a3389eb43451ca2919e134c'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'El mejor curso virtual que he llevado. Hubo quices todas las semanas, pero fáciles. Uno se ganaba puntos extra si quería participar en clases. Las consultas por coreo o whatsapp las antendía muy rápido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '947f4330b5bd0c330efb657dceccddc2421dea8914a80dbea05b8985467090ff'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Bendición: no deja tareas programadas como otros profes. Las clases son claras, pero cuatro horas seguidas a veces se hace largo. Los quices y exámenes fueron colegiados y calificados por compu, pero los trabajos que el profe Acuña nos dejaba los calificaba tuanis. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '6627cb0325f564fea85507a30ace2ae3daa207a0d106b2a66d012ee5a0711150'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Las clases se van rápido, a veces nos da timpo para hacer práctica en clase, explica muy bien, atiende dudas por telegram a cualquier hora. Los quices son fáciles porque son de la tarea y las soluciones están en el libro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '83ce851b64a9d3c3fba0a94270c00b493b017153d002e2c177afd51a91ad5cb5'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'El curso es muy fácil, pero llevarlo con él le agrega dificultad innecesaria. Si uno no hace las cosas cómo él dice, se castiga al estudiante de forma exagerada. Los aspectos de evaluación no son del todo claros, pues no da explicación si uno le reclama algo. Es muy aburrido, yo ví las clases en 2x'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '1d7d7b58833e20b55b5060e1e77b2e87eed35ed2387bb3abac012a805792e4ca'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Excelente profesor, las clases algunas veces se hacen un poco largas pero explica muy claro todo. Siempre me respondió los correos. Hay que entregarle las cosas con el formato estricto que él pide sino no se lo revisa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '18eb69561463b23977edb9f86db5c435b98b4e19ffbb33a468d9588622f63f12'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Deja quices todas las semanas pero son muy fáciles (uno tiene acceso a la respuesta en el folleto), explica bastante bien la parte practica pero para curso virtual si le hace falta explicar teoría Siempre contesta rápido las dudas, da puntos extras por participación y por corregirle el folleto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'e068e9823d62a03571e182bddc73594c5a27aaf3c5c434e17ed4f2ee6a517b8f'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Deja quices todas las semanas de ejercicios de su guía, explica bastante claro y su folleto sirve de mucha ayuda, da puntos extras por participación'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '9806c868e2a5d81b5fd5e032ff23d7d413d58fd0bd811d679f8f70d8f5b7d9db'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Me gusto que siempre estuvo disponible para atender consultas por correo y por telegram. Los quices son fáciles y se pueden ganar puntos extra de parcicipación'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'afe57e61da1dc438d44ebe2f3696efaf09e31f940cc3627803beb0c54d0c0c0f'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Profesor muy cuadrado, sino se hacen las cosas como él dice exactamente, lo pone como malo o ni lo revisa, no es flexible para nada.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'cd23eb29fea9333a74363e6fc73e5d4b260878deca331005e6e2495c736460cc'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Solo usamos su libro solo vimos sus cosas y TODO es colegiado entonces no lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'cd8898b4085b6b728e021b5c505af030d68474069be912046c80bb5bde64b26b'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Buen profe, quices/tareas todas las semanas con un plazo de 48 horas para enviarlo, eso puede llegar a quitar tiempo y ser frustrante. Explica bastante claro, ejemplos de un nivel decente para aprender, muy recomendado'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '49bfcac6d47504da27b9b0ae20ab1407a79153f86376d96619f9dd076670a6cb'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ecua es un curso fácil y con este profesor más. Explica claro y conciso, para los quices se ponía en muchas varas pero eran faciles. Clase aburrida y larga.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '5cac2407c9a89c196155715ff44353f5b6bb1a7e809b695304e212b3bd4160af'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El mae es bueno, su actitud es un poco chocante y cuando se realiza consulta se va por las ramas, Ecua se pasa solito'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '4b078615718da6f190a6f87de888a05878aa17e8a3deea116070aaaf237b1786'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Excelente profesor, muy ordenado, las clases son muy buenas, da puntos extra por participar, los quices son muchos pero son fáciles, super recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'd003d98c29c020a49651bcb7e18fbbfdfadd21faf48dcd6e77910101dc94908d'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '4d8562d0af58a8149571fb0577e5401f8828a2edad5573860bab62e3cc842f13'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'En virtual, el profe dejaba un quiz cada semana, que la verdad no era mucho ya que eran solo dos preguntas. Atender las clases es lo mejor ya que da ejemplos muy concisos y explica muy bien. Él no revisa los quices, sino la asistente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '329974412400a635a7cad7e31130d03743850881a8eab463f35e09415f30d086'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Explica bien, pero muchas veces pensé que es de los profesores que creen que uno solamente lleva ese curso. Deja "tareas morales" y quices todas las semanas, y creo que podría ser más empático o sensible con los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '23a19ccd66cf4f17d291f24437211ca6e2aba37d0ce8f4759a56173acafdaee3'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Es muy ordenado en sus clases y explica muy bien. Hace quices todas las semanas y da puntos extra por participación. Es muy argollero'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'aee2523660d6adfca5a88d337adab5a6b8749d1b7c2aed29d13716859c6386ee'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El profe explica super claro, hace quinces todas las semanas, pero viene de las tareas no obligatorias (hágalas, que son el mismo ejercicio), da puntos por participar. Lo recomiendo al 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '7c4fe9ea4ea0993263c6752cae5d1a04b9ef8d169d3987672eb732143a28643a'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Caerle bien importa . Da puntos extras, pero hay que participar, ir siempre a clases y hacer las tareas morales.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2020-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1abb4edfbb0857e123929b6633ddaed22a8617661d82d322dfdbd835df5de7f6'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'No entiendo porqué este profe tiene menos de 8, matricule con él, da puntos extra fáciles de ganar y sabe explicar muy bien. Los quices vienen de las tareas así que hágalas. Un poco estricto en quices pero bueno????'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra']::TEXT[], '2020-02-22T00:00:00+00:00'::TIMESTAMPTZ, 'fa4f67db963614b59b5d91336aa721fc995008afbe1e77f9a86f396c17734d3b'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Me pareció muy buen profe, sabe lo que hace y sabe explicarlo. Explica las veces que haga falta. Recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'fac7429c09a8f871b1e438866475931c53ef57e901b0362ae69accbee034e47e'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Es muy buen profe, matricule con él si puede. Explica muy bien, siempre aclara dudas en clase, consulta, por correo o whatsapp. Se interesa porque el estudiante entienda, califica bien, buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'e070e2fc0a7a8f418a648e12b7c4fe5fb9f2b9325832efc871dabd86abcbf677'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El curso estuvo muy bien, ordenado, no muy difícil. El profe atendía consulta todos los días. A veces estricto en el aula.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-01-27T00:00:00+00:00'::TIMESTAMPTZ, '8ebaf2015f9e171e6d454f7d233c4f5a9d04a64548ada813bce8a98bde47764a'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Me pareció buen profe, explica claro, califica tranquilo, saca rato para aclarar dudas en clase o en consulta o por mensajes. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-07T00:00:00+00:00'::TIMESTAMPTZ, '4da9d5e2f0e241c64054e9b0983173a8fd789d3284689d1606e75b439e4d4b74'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes']::TEXT[], '2019-12-10T00:00:00+00:00'::TIMESTAMPTZ, '533e69fdcea13335c709eed8d40245ba52cd874fc56469cf46bdec75b6a58c68'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-12-05T00:00:00+00:00'::TIMESTAMPTZ, '837d49a032a5f8ead5cbfb5421b12ef2c9d976a38eca0842d1d19ed014fb3c31'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Las clases son muy ordenadas y entretenidas. El profe califica justo y da puntos extra si uno quiere pasar a la pizarra.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'f3a7bb23e0cb1d165b35a7c1fa790bb691d46ca89baf05950dc51d09c689732e'::TEXT, ARRAY[1712, 1713]::BIGINT[]),
    (513::BIGINT, 'Este fue mi segundo semestre con él y no me defraudó. Explica super bien, lleva un ritmo manejable, deja tareas morales de donde saca los quices cada semana, da puntos extra si uno lo corrije. Llama a cada alumno por su nombre. Se nota que le gusta su trabajo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7f385d6b66a057e30a862fba33ce26323019580abe97cf6e12ca6bb27693c1f2'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Excelente profesor de matemáticas, súper ordenado con la materia. Da bastantes puntos extra por participar y corregirlo para los quices. Todas las semanas deja una corta tarea moral de donde saca siempre los ejercicios de los quices cada semana.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'da4f4e35237fd9038362a58659d154e7112d5b0f4b9826a7af27f51f7c25b093'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Acuña es muy buen profe, puntual, ordenado. No es muy felxible, pero dentro de lo razonable. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'df57bbaa93eec8b7e2c39398bba93d854d5d8a6bc6280612b1b67a63099b2cf9'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, '17bfdaa90845005b9980bee3f09de12e7703dd7242ded4d03f0dcd967bb43048'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Le tocó un grupo complicado, pero se armó de paciencia y nos sacó adelante. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-11-02T00:00:00+00:00'::TIMESTAMPTZ, '35a3c14552c37ba99e608bb53782ce3dec7fcfbc4df6aa1282a672702d9c57f6'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Muy buen profe. Da la materia en una hora y el resto de la clase hacemos ejercicios en grupos, y aun así cumple el cronograma. Pero tome en serio las tareas porque si no está desperdiciando un 100 en quices.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-10-31T00:00:00+00:00'::TIMESTAMPTZ, '9ed01d73885e49f6a517022891a1d14fce079d896287076dd2a9d3901a78eef8'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Trabaja bien, lleva buen ritmo, vemos un montón de materia pero siempre hay tiempo para hacer ejercicios en clase. Quices copiados de las tareas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-10-18T00:00:00+00:00'::TIMESTAMPTZ, 'cc2e0ec1ee9e43ccf608fb0b310745f23ee7c66b8f11db5c21f7ee570555fe50'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Es un excelente profesor, siempre da la teoría y después ejercicios parecidos a los del examen. Hay quices todas las semanas pero son simples ya que son ejercicios de tarea que él mismo deja. Vale la pena matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-10-11T00:00:00+00:00'::TIMESTAMPTZ, '655294eff27d2c033efecdbb558dd68272a7d6d0494c8bed446a40503b617f47'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Es muy ordenado y explica las veces que haga falta. Da puntos extra si uno quiere participar. Un poquillo exigente con la disciplina, pero la verdad es que estamos en la u.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2019-10-02T00:00:00+00:00'::TIMESTAMPTZ, '7147e2f5b143423e1f3210b6321ada5ace83a50a2a057c4f845c1fc7577ae244'::TEXT, ARRAY[1712, 1713]::BIGINT[]),
    (513::BIGINT, 'Acuña explica claro, califica tranquilo y ayuda si uno lo busca, lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2019-09-28T00:00:00+00:00'::TIMESTAMPTZ, '13ee769d05d87d3a80e19bff96c02b9551fe2e53d6b429e284ca8a23cfa8eec0'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Excelente profe. Dicen las malas lenguas que antes tenía mala fama, pero solo vea los comentarios recientes aquí y verá que es bueno. Tome la clase en serio, haga las tareas y le va ir bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-11T00:00:00+00:00'::TIMESTAMPTZ, '49786617937da698c83b9f3dd9c6d3bcc3e821e410b7f79cb6cce01131a05346'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Acuña es excelente, es súper ordenado y explica demasiado bien. Hace quizes todas las semanas en los que escoge 2 ejercicios de una tarea moral que dejó la semana anterior, si usted hace esas tareas, ya tiene ese 19% en la bolsa. Califica justo. Lo recomiendo bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-09T00:00:00+00:00'::TIMESTAMPTZ, '683f5523dc891e3f4b1fa32f853c605df014f54aefcca947b735f755c0418d49'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '53b4227a8eeff4e9ec1d1c93c1dc4f19cdb8ed4bf4badfc2b63dea5070048b79'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Es un profe muy ordenado, explica súper claro, deja muchas tareas pero si usted las hace tiene ganados los quieces pues toma los ejercicios de ahí, es una excelente persona. No dude en matricular con él!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'ca03646aa4faed1c9d3c1aaae969f507868ab2899452fc5e2ed63fe353d88290'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Me lo habían recomendado, y sí es bueno. Explica como se hacen las cosas y también para que sirven. Deja tareas morales y de ahí saca los exámenes, si uno las hace va bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bcebf5e0b1895abd89cf2c1158a60eb251516472bbb95cfec9fdab8fdba94761'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Es buen profe, solo que usted tiene que practicar si quiere que le vaya bien, enseña toda la teoría en orden y es super puntual'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e09a41ac54427ffbc01d1d159aea1c93bf451d42465c2042cb9827b043ef8934'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Buenas clases, la materia me costó pero siempre estuvo disponible para ayudar en la oficina, en clase o por whassap.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '084bc7d158b41445b877761b4d09f6253204472fb88629a4a74761a992b06dfd'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'El curso me costó pero el profesor todo el semestre estuvo dispuesto a aclara dudas en clasesy en consulta. A veces pierde la paciencia pero en general es bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5c8def2d9b7372f8135683f36dae1a4b4893b750f8e33e82d726c0651c292143'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0f42b125befcb4982ed98fb1f2018122cd593465899af8fc88346d45f398f5f4'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '51b363586eb9958917eec079b223698c6fdd1095715e87856de314c7f8ce9e11'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Clases interesantes. Buen trato. Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ea588b092daf8c4396f58a13825f7eaee2d673464fa89e312d52eaf3e7f94112'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El profe explica bien y ordenado. Siempre dispuesto a yudar con las tareas. Todo el grupo le pasó.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'fafed15377d304d55573e2bc7fef4fc1767c1a8ac10056dfba89d7f87c8d41bd'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Se le entiende bien, tiene paciencia. A veces estricto.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-04-15T00:00:00+00:00'::TIMESTAMPTZ, 'c104a1ef3c814696e5a48884eda3eb1b76026793aaf25c04e36a36692209f953'::TEXT, ARRAY[1049]::BIGINT[]),
    (513::BIGINT, 'Ordenado. Aclara dudas en clase y por teléfono o correo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2019-04-06T00:00:00+00:00'::TIMESTAMPTZ, '7a231e644edbb428bf92deedf8d42e5ca314289c4872f310fb603592b2376d41'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-03-26T00:00:00+00:00'::TIMESTAMPTZ, '050fcce7d15bd58eed4a257b50ff99d71f3e77293cbb66179915f7eff44f333c'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Sabe mucho. No será muy gracioso pero enseña claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-03-02T00:00:00+00:00'::TIMESTAMPTZ, '5c3d7b98a1a468ac8d8d17d347329b6a43e69c28816a94e25d4d55c058bb4b69'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Explica bien y explica atajos para simplificar. Los quices semanales son una ayuda porque son copiados de la tarea, ademas que así uno va con la materia al día y cada quiz evalua solo una semana de clases. Al llegar al examen uno solo repasa. Da puntos extra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2019-02-26T00:00:00+00:00'::TIMESTAMPTZ, 'cd8654dddad1ada4baf6a10bc814d2e1a158b5386bec1571aea41c849d62dfdc'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Explica bien y sabe bastante pero hace quices todas las semanas y si un día falla lo hace la próxima lección , se convierte en un curso pesado, talvez el curso este orientado para carreras de baja carga académica.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa']::TEXT[], '2019-02-25T00:00:00+00:00'::TIMESTAMPTZ, '2a9e4a0faaeff17b6536a866c68fa2be71bd5329f05db8052fdb40af1826c8a5'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Muy dinamico y ordenado, califica normal'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-04T00:00:00+00:00'::TIMESTAMPTZ, '66e6c59d1b256245e597607fa796295ba0fea61b6e2accfaa0e68d8bd87520b1'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-23T00:00:00+00:00'::TIMESTAMPTZ, '5d859273ba98e00dd2a58e924934cbbf3f6ab10f44a66f8148e5b4275b6b5425'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Deja tareas morales del folleto todas las semanas de donde extrae los ejercicios más fáciles para los quices que son semanales también, por lo que eso ayuda a ganarse ese porcentaje de manera fácil y estar al día. Es ordenado y no califica rudo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2018-12-04T00:00:00+00:00'::TIMESTAMPTZ, '387af2df937902dfd95569cf7387c06229217f5b6ac460504123d12fde6dea5a'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'a419c459302722db6b65af0ae9455593266c1c8fbc4a4f58f53246f41f0f21cf'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '2e302cd3ec4ef71b0847ab1ba220976e10c65e1699e274e757040f726e2a123e'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Todas mis consultas tanto en clase como por correo electrónico el profesor muy amablemente me las respondió, mostró interés por el aprendizaje y que pusiéramos atención en la clase. Es un profe que sabe bastante sobre la materia que imparte.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'f30bbaad63c5a9c2f14d4a72a5aecb6da4b8f252cd214edc1c3d6c3b0f1b786b'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '4dc7a6dd331f2659866965a62d387bdcb99cbe225867bb67df04c71cd9fc1efa'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Ay que ponerle, pero el profesor explica muy bien y ayuda con puntos extra'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'b7201c8cfa360ab6051dfe1914470a6290c84b525fb2abb5f2337cf9b95e7eec'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '6597d498abc33e40b39f8f714994b966c353efc30097eb495c0a2097db6a859d'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Buen profe, justo, accesible'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a9444304a1bcbf77969f986e498c86d7b1701a5a7551a4ad18d644d37214cc3b'::TEXT, ARRAY[1679]::BIGINT[]),
    (513::BIGINT, 'Explica muy claro, lleva buen ritmo. Exámenes tranquilos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '7fb0ee2a62d4996f87b6077a7875d1181086d7797e4d5f607122fdd4a74069be'::TEXT, ARRAY[1712]::BIGINT[]),
    (513::BIGINT, 'A mi me fue muy bien con el, explica las cosas fáciles y da puntos por ir a la pizarra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'f94cd928ce6d5d767c9d51ef5c25d32b99e72028898c0c0a15c55262a6358556'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Explica bien, da puntos extra por participar, ayuda dentro y fuera de horas de consulta. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-13T00:00:00+00:00'::TIMESTAMPTZ, '69859a7ce64ed2d5d29c262e591122e926156eb28545ac46aac3996e7d81ef23'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Me parece un excelente profe. Muy ordenado, se le entiende bien, da puntos si uno quiere paasr a la pizarra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2018-09-22T00:00:00+00:00'::TIMESTAMPTZ, '23bca8537539061cfb4af3d0fafd664378bd0d4f67d8bbe2cf790d184398f20e'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2018-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'bb72d93fb1ae65283f49f67196f264d6634d2d3d9d5b6ec042de5bfc7c445292'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'No alcahuetea, pero sí es justo. El que se esfuerza sale bien y aprede un montón.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'ae78fb41f65b1661650b55e503bf5bc6e42144817b5034247a91f429ee1a2e4c'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Me pareció un excelente profesor. Es muy ordenado dando clases. Califica según lo que se vio en clase y siempre aclara bien las dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-07-09T00:00:00+00:00'::TIMESTAMPTZ, '61992f3dc99428b9b5c19216291ecf17f8c77154c12b35f56886ca416613b405'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Muy buen profesor, hace quices cada semana lo que ayuda a llevar la materia al día. Califica lo justo y explica muy bien ya sea en clases o en consulta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '0599717500ba2463bedf2230ad1a32cacffc5508e6df522927efaee2f4ab346c'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Muy buen profesor, va bastante rapido con la materia, pero super claro. Revisa todo super rapido y de una manera eficaz. Los puntos de participación lo pueden salvar a uno.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6a0695e7fbe30c700596c910e32488f94b4c44b5174f2e29ea3593d53b73c842'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Muy bueno. Hay que saber coger el ritmo y no aflojar, pero el profe es bueno.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b16fdd6c578ac8d70c69a0db4baa66b2699b6bf5c5dec05aa8031d23d24ab1d8'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'A mi me pareció un profe justo y razonable. Si uno le habla el entiende y ayuda, si es considerado cuano uno le expilca aunque tampoco regala notas. Quices todas las semanas y eso ayuda a llevar la materia al dia y no tener que correr para los examenes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b91c041fd4785522d81d646b216c8e7dbf5e11e1c2b63c1138cd451fa443e6e2'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Tareas y quices todas las semanas, explica bien pero su actitud es terrible y no le importan los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '31f392979b05d680a76cbdfda9581744fdbac42da90a0b00ec7ba98e4fb7ee87'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'No es nada buena persona y explica bien pero con esa actitud no dan ganas ni de preguntarle nada'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3ee531972841411a285de40cae2a9d97e13dd2d3e29f6db476e8a60b73d1ecb'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Califica justo, da puntos extra, se le entiende bien, aclara dudas, muy ordenado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5e677d036d6d5ca11dfc81e68ff1c285ba0d030c64d1be37a50e8706b1900cd6'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Buen profesor, las clases son un poco aburridas pero sí explica y se le entiende. La tarea que deja ayuda mucho para que no se acumule la materia para el examen'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '90cbb17b9c9eb456a1bd7fd32419c48b1cadbd4565d35350b80a8c1cba81e7db'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'No es que sea fácil, pero me parece que califica justo. Explica bien y da ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '900b2d2c7b7200a95e25204ea2820bdeae47c5fd16252a1c6412dc107aeee268'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'No es el mejor profe, deja tareas todas las semanas, si uno las hace pasa de fijo, y aunque es medio arrogante a veces, le ayuda a uno en todo lo que puede y cualquier duda que uno tenga, se la explica todas las veces que uno necesite'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2018-05-30T00:00:00+00:00'::TIMESTAMPTZ, '369761c21e45e1b7f5186a94079c6308dc591ca6ef47d028a1db3b553d67edd5'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Después de pulsearla un monton de veces por fin voy a pasr este curso gracias a Luis Acuña. Muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos exámenes']::TEXT[], '2018-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'b8318d5bf82dfb3ced9d0fb27eac760bca7921448da4de368bbec4e9f3a2c137'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Es manejable mientras uno vaya a clases, porque si se pierde una clase ya vieron un monton de materia. Los quizes son regadados si uno hizo las tareas. En los examenes da puntos aunque uno no termine la pregunta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-03-28T00:00:00+00:00'::TIMESTAMPTZ, '599ebd9a5209c67851ca2407fb0d58d4f56834aee6b4ea824b8a679cc66b2287'::TEXT, ARRAY[1653, 1667, 1647, 1668, 1655, 1648, 1654]::BIGINT[]),
    (513::BIGINT, 'Me habian dicho que era duro, pero a mi me fue muy bien con el, explica las cosas fáciles y da puntos por ir a la pizarra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2018-03-04T00:00:00+00:00'::TIMESTAMPTZ, 'c3905c1c5658c0b6a900e69945cac1149332190686e5b3c2821fe62701bdc23e'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Excelente profesor, explica muy claro, ayuda mucho si uno va a consulta. Deja muchas tareas y de ahí salen los quices. Sea responsable, pongale y verá quele va bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2018-02-21T00:00:00+00:00'::TIMESTAMPTZ, '7aa1f60ca70d032c92bc354d158a919748f5ddb3437c8eab7c7691b466302603'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'No les recomiendo tomar clases con este profesor si usted quiere un profesor justo e imparcial. No es el mejor profesor.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-02-19T00:00:00+00:00'::TIMESTAMPTZ, 'd114b2bd88c4ae0cc0ec9bec7537690eb8b020fb7c3f44796bc909da92850bdf'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Buen profe, muy ordenado, explica muy bien la materia, haga las tareas, ponga atencion y le va bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'ffd24ef0dbb1eef0a608afdef8b0e63493eabc3f0d41e89c5eef4cc52049d512'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Me habian dicho que era un sonador, pero no, tranquilo, muy ordenado. Al final me ayudo porque por poco me quedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '56dfa3742c0837fc39c639dabbdb206ebb79bbec5583860646424d4246eb27cb'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Si usted hace las tareas y saca las dudas, ya va bien para los quices y los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'fd1511dc99facc8ed1b03760c81b1244efd0fd1c549aa7615a12002b5d3d21ed'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Clases entretendas y claras, ayuda si uno le pide ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '0263e179984d69edeb9743fa780ff7e4c217465c34312875e628bac18e155ce8'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'La primera vez perdi el curso por vago, pero lo repeti con el porque la verdad es que es bueno, y la segunda me fue mucho mejor. Si uno hace las tareas va bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '9d9a54e607c6f1784ad170215a702d55f3e4d8d0cac25b387ec8be1baf3617bf'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Puntos extra por pasar a la pizara. Deja tareas "morales" y de ahi saca los quizes. Atiende consultas por correo y whastsapp. Muy ordenado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-01-21T00:00:00+00:00'::TIMESTAMPTZ, '918e7acb8e5c4e7f3945e4a8a0a4a0280644355fae4b8f233d683ee7554a6aec'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Es un excelente profesor, realmente siento que uno va a prender y aprende bastante, los quices y tareas son sencillos, se esfuerza para que el estudiante aprenda y entienda lo que hace, horas de consulta adecuadas al estudiante y trato respetuoso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-21T00:00:00+00:00'::TIMESTAMPTZ, '05971e857b7d8c488d063d3cda78fd9f8066504d7fcfac4444e16cbd4899c58d'::TEXT, ARRAY[2439, 2444]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Exámenes retadores']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, '195440015849ca587fe22022ba34f89ccf1f56e7182958f1486a497b02bc0988'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Me parece que es un excelente profesor. Es sumamente ordenado a la hora de impartir sus clases. Califica de acuerdo con el contenido visto en clase y me parece que siempre responde adecuadamente a cada duda. Totalmente recomendando.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, '909f5a7a235d336968836f5c7dce45a3e2dd452ad98f9807a5134d1bef639aab'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2017-12-29T00:00:00+00:00'::TIMESTAMPTZ, '599c5c526e033fb13ad95f409abb80fcaae3b9b275f2e7089f41e0ead8d36c86'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Es un excelente profesor, explica la materia de forma muy clara, deja muchas tareas y quices, lo cual ayuda a practicar y estudiar. En horas de consulta ayuda bastante. La clave para pasar el curso es respeto, disciplina y estudio. Es un profesor muy justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-26T00:00:00+00:00'::TIMESTAMPTZ, '673046261397bd0478b5b545c2f9b2a89670880c4562844e73b4621ef0d1042d'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Hay quices todas las semanas. Por cada clase deja tarea y revisa solo 5 o 6. No es tan dificil pero hay que dedicarle MUCHO tiempo, da puntos extra por participación si pasa a la pizarra para revisar los quices, exámenes y si hay dudas de la tarea. Si son bonitas les da muchos pts por participación.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'f990ef0500cc4cd3cbb3adfddc4299261c63a224f4104ca5cd2d1d23a8d309b1'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Como profesor no es el peor. Sí se le entiende pero califica muy rudo. Da puntos extra por participación. A mí me cae medio mal pero no es lo peor. Matricule con él solo si es de sus últimas opciones.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f9ffcbedf098c8f72f2016c9feba8d492b040b368cf3647047f0aa6e2a3b76e3'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'No es un mal profe como muchos dicen, quices todas las semanas pero saca los ejercicios de tareas que el deja y da puntos extra por participación.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9e12b1f2a23cdb9e0b3043bdb52ce545cf9274db4e5961de3563aef21e6eed3c'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Un excelente profesor, le gusta la gente responsable. Ayuda mucho con el porcentaje de quices. Deja muchas tareas que al final son los quices. Comprométase con el curso y es muy probable que lo pase con buena calificación, participe en clases y no falte.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0b74ff5fac6d3e82e2957fec6ef388acad9b4fd70bd3f0a1968c756df338331e'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'EXCELENTE'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '449c4fb1242c09ac7ef62ca082db427aee809e2ffe6157ca8327891121f834d2'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Ayuda mucho, las tareas que deja básicamente son los quices, da puntos extra y aclara las dudas. Es un poco formal a la hora de escribir los ejercicios, en los exámenes hay que poner todos los pasos que uno realice.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'f691a572f8a3bd4a3c94ca679781514e68e574d865801d7ca65d7c59292615be'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Da muchos puntos extra por pasar a la pizarra, no sera el mejor pero tampoco es tan malo como dicen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Muchos exámenes']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '85a39e89bf43f67bdc5b48a559796784306c8a38df1a5432b82e27279a8c2920'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '3cf2e5b0965e5db7f2c66ea243cc7506d203df804587fc3684f9e0ed6064d835'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '1b2c3cae5f86f297900fe3990ad5b59ecb4632e2b47d8bdcbf6ae1b0a245616f'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'No será el que tiene mejor reputación, pero es excelentes, soy hombre y me dio un trato justo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '819a7fed885e698ca9433d764201a0299e0e1cbf86b553e88e88d6c820f4c461'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'quices todas las semanas, el curso se basa en los folletos que él envía, las clases son aburridas, da puntos por participar, lo bueno es que se puede faltar a clases porque el avisa los días que realizará los quices'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra']::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b860de326c047d0296eaa615a41d3fe516b247e7c4b1fbb36f72639b3dce599b'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Me parece buen profe, da puntos extra, hace quices faciles y da puntos extra, pero no se preocupa para nada de los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b51479c8bac0f1c9f271c12cc6995c383ff31edc32f10ba082cb446c57296c14'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd131c8cf785678d0a28cbfaaf5c5a1096fe4fa99798e1226527ef2eb5b6b8042'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'si va a clases el curso se hace bastante llevadero, el promedio de quices es casi regalado si hace las tareas, y para calificar es justo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b0304ff6899449fa2b3c78aee7391f75a75c94bd8b27e8746528eb11cd0a9366'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Es importante asistir a las clases eso lo toma mucho en cuenta y sacar buena nota en quices los cuales hace uno cada semana sin falta y también deja tareas una por semana no obligatorias.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '3e0846ef023fe85f932f26e7386737f6a83019f8a97c1e21f668451cf9d3a531'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Necesita una visita de las autoridades de la oficina de equidad de género en sus clases.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2016-02-11T00:00:00+00:00'::TIMESTAMPTZ, '579e0ebc56447992f7297df19a9b5041746043bb3121bbe5ee824b97c28762ef'::TEXT, ARRAY[260, 2439]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-02T00:00:00+00:00'::TIMESTAMPTZ, '3063ee158bb6d4b1bcb5a71f593e0f52cdd122a0bc6fb6b6bc7bcfdeb3adabc9'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, '59e7121b4493881bd5a5d25e2d67dee15047d2979eabf7d62a2e377c61d9d314'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (513::BIGINT, 'No explica el contenido con claridad se enreda mucho'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'd935879fa7467a33e6e9d7fee3180f8e386800286dfd86b61c79735619139096'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'e9c6223f0cbf7a7e812fe272c8931bc5cfb764983469846098e03ceb070832d4'::TEXT, ARRAY[1669]::BIGINT[]),
