    (513::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '9602d84c9ff0b72bf358f9adf7e88ab84ba2d6c770b5493a2b8da16985d58dd8'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'El profe es organizado, claro. Nos ayudaba a ganar puntos extra corrigiendo examenes, participando, mandando ejercicios extra. Es cuestón de ponerle ganas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '3391163faa0dde70c2008e4ad28ef176780069fc658b84c0fdea492f12226bd5'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Muy recomendado para los que quieran coger el curso en serio y esforzarse por ganarlo. El profe reconoce el esfuerzo y ayuda con muchas formas de puntos extra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7f1b1170c3b1b42bcc380620849a5666b0fe976ae171a261f3bc6117f63e8b92'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Pésimo profesor, le gusta perjudicar a los estudiantes, tiene preferencias con los que participan, es un incómodo 0 comprensivo, por mucho el peor profesor con el que he llevado un curso'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cdb0444defdc354096e3ea48b558c57ebf2c300f824910499badd4feb474531d'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Recomiendo al profesor para personas que ya sepan sobre el curso, si lo está llevando por primera vez y se considera una persona introvertida no se lo recomiendo, es buen profe, pero se molesta con facilidad y suele dar preferencia a las personas que más participan y saben sobre el curso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e61965ee5228c0ba30af9ed7a5a5a83dcc4fbc7f6c86614c3f01b8ae81a92e05'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'El curso no es que sea facil, pero el profe da muchas oportunidades de mejorar las notas, como participar en clase, hacer correciones de examenes, mandar trabajos extra por correo. Ademas los quices son ejercicios de las tareas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'f5edfc21ff19c1c00514cffa24260258780aff50af4f5fbc2b00fdccfac58ede'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Por fin pude llevar este curso con un profe que sabe explicar. Da puntos por participar o corregir errores, califica justo, atiende consultas rápido, muy muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2026-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'ea2732736da72fb18447461dce208dfdd775f72e5b68e2f44fef0e72c9155b53'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Es un profesor excelente, explica a un buen ritmo, si es necesario explicar de nuevo o devolverse lo hace, le interesa que usted aprenda y pase el curso siempre y cuando note su esfuerzo, si participa en clase le da puntos extra, deja tareas y quices fáciles cada semana, lo recomiendo totalmente!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '5e6959dff1d6d13ed589e67f2c35f3fa186fd57c9854696a4c021d2b1bd97885'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Fácilmente el mejor profesor que he tenido en el TEC, explica muy bien, le gusta mucho que el estudiante participe en sus clases, hace quiz que son los mismos ejercicios de las tareas que manda, valora mucho el esfuerzo y dedicación del estudiante y lo premia con puntos extra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '79d3ac81d59ad9995df6bd46e4a65ca534555b3c6050618985b476f12f284368'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Era un grupo semipresencial, teníamos clase unas semanas y otras nos mandaba videos de él mismo dando la clase, entonces todo bien. Tareas virtuales y quizes presenciales sacados de la tarea.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-18T00:00:00+00:00'::TIMESTAMPTZ, '8415f1e4de54851a908a9850c6d623d98e6f2db53744bc27d9063193db328d29'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Explica bien, da puntos extra por participar. Hay quiz o tarea todas las semanas. Lo super recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2f4fb6e2a8c05c3ca4e281482d94004e335ce9415a8110129d21310ff0cbcd2'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Explica bien, califica tranquilo. No es que regale puntos, pero sí se pueden ganar puntos extra si uno se interesa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra']::TEXT[], '2025-07-08T00:00:00+00:00'::TIMESTAMPTZ, '8cf6a3bd7d14e2f5ef4e728dd09b4e08884a5b78ef49fa86f7cd0bb503f633ce'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Muy buena explicación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '4e5779b9cac9eb215bf84e3b6277ba018f0926e963461537cb3b52f83513d92f'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '94b3a84d347d8021b534c151e1d1a2cb1619b169e1049ffe6e3578fd91838e40'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Excelente profe. Esta es la segunda vez que llevo el curso, me recomendaron que lo repitiera con Acuña, y no decepcionó.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-05T00:00:00+00:00'::TIMESTAMPTZ, '6fedcdf3f8ec5ec3c286b88c8d1c41e410fbb5af492c2f08cd221a94abc623f8'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Las clases son buenas, los quices son fáciles porque están sacados de las tareas, el profe es bueno. Si yo me quedé fue por vaga, pero espero que lo dé el semestre entrante para repetirlo con él, porque vale la pena.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-16T00:00:00+00:00'::TIMESTAMPTZ, '8185e6a519703bb82a39556d48acf7aa98c0a5a7512f78b7e1a85081e885561a'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'Bella persona, desde el principio del semestre dispuesto a ayudar en clase o consulta. Las clases son largas pero es culpa del horario, él hace varios recreos y uno se despeja. Sabe montones y sabe explicarlo. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '856d789bdfd11fdd09b3a7b21ba14ffafdd6bdd41ee674c69637e0c61b599090'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Es bastante claro, todas las semanas hay quiz, si usted participa le da puntos extra y los exámenes son fáciles. Eso si las clases son largas y se enoja con facilidad, a veces prefiere solo ayudar a los que participan más.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7b52dd8131637253878518535767ae2ee3159df593ac9dd756d8e242313ea734'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Es un buen profe, sus clases son bastante largas y de prestar mucha atención. Si uno falta se pierde de mucha materia, hay quices todas las clases, cae bien solo que se enoja con facilidad. Y la participación es lo más importantes (son puntos extra)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6ce3e428c749688030ba3bfa427e25844e04d39a427561f10f51b36c66604eba'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'La teoría y ejemplos que explica en la clase se entienden, pero hace muy pocos por tema y de poca dificultad. Cuando uno está estudiando con los ejercicios semanales que deja, se da cuenta que no sabe cómo resolver ejercicios más complejos, hay que estudiar todo por su cuenta para salir bien :('::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e5a3ffca2513aa1e1fc45b347c2d1044d34aed93fc7d2a90676c0a62aa8e81cf'::TEXT, ARRAY[1669]::BIGINT[]),
    (513::BIGINT, 'El horario es de cuatro horas pero el profe Luis hace recreos frecuentes y la clase se va rápido. A mi me pareció claro y los exámenes eran sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'cccabc03d0a8e8eb87c3f8937fd9df844fdc9089a869cc631120a54b3c198ced'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Es un excelente profe, volvería a llevar cursos con él, el curso es muy llevadero (en verano), explica súper bien, da puntos extras.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-22T00:00:00+00:00'::TIMESTAMPTZ, 'e9e7af5445694a7803992d8ee13d835ac0b491b273855ec11985c8d408d23593'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Acabo de llevar cálculo en verano, y Acuña es de los mejores profes q he tenido en le Tec. Explica muy bien, se ve que le gusta, nos hizo 6 exámenes de una hora, y lo sentí más fácil que 3 parciales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes']::TEXT[], '2024-01-26T00:00:00+00:00'::TIMESTAMPTZ, '29fc66440a4eeef220c1e320c602f89448af7583c2770fd11e0613a211aedd41'::TEXT, ARRAY[605]::BIGINT[]),
    (513::BIGINT, 'Claro, entretenido, califica justo, el curso no es complicado, y vemos muchas aplicaciones. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '91fc7aa9aa16954f12e702a3afe0d6faedc3deaeaf5d1c1e059179aa888d4cb2'::TEXT, ARRAY[1712, 1713]::BIGINT[]),
    (513::BIGINT, 'Un poco serio, pero muy buen profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-11-06T00:00:00+00:00'::TIMESTAMPTZ, '39ddcdf2634acbeda076d53612504ced2df0df719a7c439f7978fca934173501'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Las clases son muy claras y bien organizadas. El profe claifica tranquilo en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-09-18T00:00:00+00:00'::TIMESTAMPTZ, '4e2f3478d25b234ccdd7344902af7a3163fa8ab27f5516f404004eebc0cda593'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'Para mi lo mejor fue que cada día el profe deja como 5 ejercicios de práctica "tarea moral" y de esos uno viene en el quiz de la próxima semana, asi que si uno va haciendo las tareas ya va volando en los quizes, y sí pura vida.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '01d7fa49ce6322616675ff5123de4c9b56b7d666a8173dfbe48c8690eca082e4'::TEXT, ARRAY[935]::BIGINT[]),
    (513::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ff927ff6c92b29bd2210ac29c7163e06d331e83e245e7cd385d1f3820e44d450'::TEXT, ARRAY[1712, 1713]::BIGINT[]),
    (513::BIGINT, 'x2 lo que dice el de mate básica. El semestre pasado llevé álgebra con Acuña y todo bien, claro, orgnizado, puntual. Este semestre llevé ecuaciones con otro profe que es un desastre, se enreda solo, se atrasa con el cronograma. Si tengo que repetir Ecua trataré de meterlo con Acuña.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '154a11f67cc827562110a883c9a575382bd0ca41d5897ebd61f20b25bddaa682'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'El semestre pasado llevé mate básica con el profe Luis y lo pasé de lo más bien. Este semestre llevé cálculo con otro profe que nada que ver. Así es como más se nota que el profe Luis es bueno, comparándolo con los otros.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'adf28efcdab3e43e1eb68c3fc03b8e1a5389b89a12c50f1c7ddfa2d4432fe136'::TEXT, ARRAY[2439]::BIGINT[]),
    (513::BIGINT, 'No es que el curso sea tan difícil, pero tampoco es complicado y el profe lo pone todo muy claro. Si usted hace las tareas y lleva la materia al día, los quices están pasados y para los exámenes solo hay que repasar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-04-10T00:00:00+00:00'::TIMESTAMPTZ, 'c6b341a45432449892892607ee337f8bffc9ac12340eee7437f88e086fcdf023'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'Ya me gradué pero hace años llevé cálculo con el profe Luis. Fue uno de los cursos más difíciles y lo llevé tres veces, pero a este profe por fin le entendí, explica de distintas formas hasta que uno entienda, es paciente y ayuda en horas de consulta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-13T00:00:00+00:00'::TIMESTAMPTZ, '1081e03f5eb59cebc5f932e0eb2773efe1956b6f20ae4316408d28d449d807b4'::TEXT, ARRAY[2444]::BIGINT[]),
    (513::BIGINT, 'Muy buen profesor, las clases a veces se hacen un poco largas pero explica muy claro todo. Siempre me respondió los correos rápido. Hay que entregarle las cosas con el formato estricto que él pide, pero es cuestión de fijarse bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'caf2f51038a9c4acbd79fb0f100d4bdd143eb1b42cd85fa88a99c17071dc7903'::TEXT, ARRAY[634]::BIGINT[]),
    (513::BIGINT, 'El profe es bueno. Ahí otros compas seguro se embarcaron matriculando en virtual sin saber lo que era y no les gustó. También pusieron que el curso no les interesaba, obvio. Pero si uno le pone, el profe explica bien, ayuda, resonde rápido, y es cuestión de ponerle ganas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-01T00:00:00+00:00'::TIMESTAMPTZ, '7d140ea57c5af98bab70e00a6cd4681a1aae69dc575a35e39cb8b5fb7eaf4f71'::TEXT, ARRAY[2439]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
